"""Exercise Bayer tests without making the optional frontend a base dependency."""
import importlib.abc
import sys
class WithoutEinops(importlib.abc.MetaPathFinder):
 def find_spec(self,fullname,path=None,target=None):
  if fullname=='einops' or fullname.startswith('einops.'):
   raise ModuleNotFoundError("simulated absent optional einops",name=fullname)
sys.meta_path.insert(0,WithoutEinops())
import pytest
raise SystemExit(pytest.main(['-q','tests/test_nonlocal_raw.py']))
